WIDTH = $WIDTH;
DEPTH = $DEPTH;
WALL_THICKNESS = 200;
WALL_HEIGHT = $WALL_HEIGHT;
ROOF_HEIGHT = $ROOF_HEIGHT;
ROOF_RIDGE_PERC = 50; // TODO in Roof

//// INTERACTIVE DIM LINES ////

line([0,0,0],[WIDTH,0,0]).tmp().moveY(-1000).dim().param('WIDTH'); // WIDTH
line([0,0,0],[0,DEPTH,0]).tmp().move(-1000).dim().param('DEPTH'); // DEPTH
line([0,0,0],[0,0,WALL_HEIGHT]).tmp().move(WIDTH+1000).dim().param('HEIGHT'); // HEIGHT


//// MAIN ////


wallFrontComponent = $component('./timberwall', 
                       { WIDTH: WIDTH-2*WALL_THICKNESS, HEIGHT: WALL_HEIGHT, 
                          DEPTH: WALL_THICKNESS,
                         OPENING: true, OPENING_LEFT: 500, OPENING_WIDTH: 600, 
                         OPENING_HEIGHT: 1600, OPENING_SILL: 100, 
                         ROOF_HEIGHT: ROOF_HEIGHT, ROOF_RIDGE_CENTER: ROOF_RIDGE_PERC }
                      )
              .model()
              .move(WALL_THICKNESS, WALL_THICKNESS/2)

wallFrontComponent.name('wallFront');


wallLeft = $component('./timberwall', 
                  { 
                    WIDTH: DEPTH, HEIGHT: WALL_HEIGHT, DEPTH: WALL_THICKNESS, 
                    OPENING: true, OPENING_LEFT: 1000, OPENING_WIDTH: 600, OPENING_HEIGHT: 1000, OPENING_SILL: 500,
                  })
              .model()
              .rotateZ(-90, [0,WALL_THICKNESS/2,0])
              .move(WALL_THICKNESS,DEPTH-WALL_THICKNESS*0.5)
              .name('wallLeft');

wallRight = $component('./timberwall', { WIDTH: DEPTH, HEIGHT: WALL_HEIGHT, DEPTH: WALL_THICKNESS})
              .model()
              .rotateZ(-90, [0,WALL_THICKNESS/2,0])
              .move(WIDTH,DEPTH-WALL_THICKNESS*0.5)
              .name('wallRight');

wallBack = $component('./timberwall', { WIDTH: WIDTH-2*WALL_THICKNESS, HEIGHT: WALL_HEIGHT, DEPTH: WALL_THICKNESS,
                        ROOF_HEIGHT: ROOF_HEIGHT, ROOF_RIDGE_CENTER: ROOF_RIDGE_PERC })
            .model()
            .moveY(DEPTH-WALL_THICKNESS*0.5)
            .move(WALL_THICKNESS)
            .name('wallBack');

roof = $component('./urroof', { SPAN: WIDTH, HEIGHT: ROOF_HEIGHT, DEPTH: DEPTH, 
                                OVERHANG_SIDE: $OVERHANG_SIDE, OVERHANG_FRONTAL: $OVERHANG_FRONT })
            .model()
            .moveZ(WALL_HEIGHT)
            .name('wallBack');

structureElems = all().filter((s) => !s.name()?.includes('insulation'));
modeler.make.partList(structureElems);

structureElems.iso().move(10000)
